import 'dart:math'; import 'package:flutter/material.dart';
class FourInRowGame extends StatefulWidget{const FourInRowGame({super.key});@override State<FourInRowGame> createState()=>_FourInRowGameState();}
class _FourInRowGameState extends State<FourInRowGame>{final b=List<int>.filled(42,0);bool done=false;void play(int col){if(done)return;for(int r=5;r>=0;r--){final i=r*7+col;if(b[i]==0){setState(()=>b[i]=1);if(_win(1)){setState(()=>done=true);return;}Future.delayed(const Duration(milliseconds:220),_ai);return;}}}void _ai(){if(!mounted||done)return;final cs=[0,1,2,3,4,5,6]..shuffle();for(final c in cs){for(int r=5;r>=0;r--){final i=r*7+c;if(b[i]==0){setState(()=>b[i]=2);if(_win(2))setState(()=>done=true);return;}}}}bool _win(int p){for(int r=0;r<6;r++)for(int c=0;c<7;c++){final i=r*7+c;if(c<4&&[0,1,2,3].every((d)=>b[i+d]==p))return true;if(r<3&&[0,7,14,21].every((d)=>b[i+d]==p))return true;if(r<3&&c<4&&[0,8,16,24].every((d)=>b[i+d]==p))return true;if(r<3&&c>2&&[0,6,12,18].every((d)=>b[i+d]==p))return true;}return false;}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Four in a Row')),body:Column(children:[Text(done?'انتهت الجولة':'دورك',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w800)),Expanded(child:GridView.builder(itemCount:42,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:7),itemBuilder:(_,i)=>GestureDetector(onTap:()=>play(i%7),child:Container(margin:const EdgeInsets.all(2),decoration:BoxDecoration(shape:BoxShape.circle,color:b[i]==0?Theme.of(c).colorScheme.surfaceContainerHighest:(b[i]==1?Theme.of(c).colorScheme.primary:Theme.of(c).colorScheme.error))))))]));}